using MunicipalPlatform.Api.Platform.Tenancy;
namespace MunicipalPlatform.Api.Modules.Operations.Domain;
public enum ChangeRequestState{Requested,Analysis,Approved,Planned,InProgress,Delivered,Rejected}
public sealed class ChangeRequest:ITenantEntity{private ChangeRequest(){} public ChangeRequest(Guid municipalityId,Guid requesterId,string title,string businessReason,string impact,string priority){Id=Guid.NewGuid();MunicipalityId=municipalityId;RequesterId=requesterId;Title=title.Trim();BusinessReason=businessReason.Trim();Impact=impact.Trim();Priority=priority.Trim();State=ChangeRequestState.Requested;CreatedAt=UpdatedAt=DateTimeOffset.UtcNow;}public Guid Id{get;private set;}public Guid MunicipalityId{get;private set;}public Guid RequesterId{get;private set;}public string Title{get;private set;}=string.Empty;public string BusinessReason{get;private set;}=string.Empty;public string Impact{get;private set;}=string.Empty;public string Priority{get;private set;}=string.Empty;public ChangeRequestState State{get;private set;}public string? Decision{get;private set;}public string? PlannedRelease{get;private set;}public DateTimeOffset CreatedAt{get;private set;}public DateTimeOffset UpdatedAt{get;private set;}public void Transition(ChangeRequestState state,string? decision,string? plannedRelease){State=state;Decision=decision?.Trim();PlannedRelease=plannedRelease?.Trim();UpdatedAt=DateTimeOffset.UtcNow;}}
